// AVX2 4-way interleaved SHA-256 (independent lanes) to measure throughput potential.
// Also a carefully written scalar version with full unroll + manual scheduling.
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <immintrin.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
