    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

// 4 independent SHA-256 states processed with AVX2. Each lane hashes its own buffer.
// Used only for throughput measurement of the round function.

static inline __m256i rotr_epi32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32 - n));
}
static inline __m256i bswap_epi32(__m256i x) {
    const __m256i mask = _mm256_set_epi8(
        12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3,
        12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    return _mm256_shuffle_epi8(x, mask);
}

// Process one 64-byte block for 8 independent messages (two AVX2 regs of 4? let's do 8 via two groups... just 8 lanes = 2 ymm)
// Simpler: 8 lanes using two __m256i. To keep it readable, do 8 independent messages.

typedef struct { __m256i v[2]; } m8;

static inline m8 m8_add(m8 a, m8 b){ m8 r; r.v[0]=_mm256_add_epi32(a.v[0],b.v[0]); r.v[1]=_mm256_add_epi32(a.v[1],b.v[1]); return r; }
static inline m8 m8_xor(m8 a, m8 b){ m8 r; r.v[0]=_mm256_xor_si256(a.v[0],b.v[0]); r.v[1]=_mm256_xor_si256(a.v[1],b.v[1]); return r; }
static inline m8 m8_and(m8 a, m8 b){ m8 r; r.v[0]=_mm256_and_si256(a.v[0],b.v[0]); r.v[1]=_mm256_and_si256(a.v[1],b.v[1]); return r; }
static inline m8 m8_not(m8 a){ m8 r; __m256i m=_mm256_set1_epi32(-1); r.v[0]=_mm256_xor_si256(a.v[0],m); r.v[1]=_mm256_xor_si256(a.v[1],m); return r; }
static inline m8 m8_rotr(m8 x, int n){ m8 r; r.v[0]=rotr_epi32(x.v[0],n); r.v[1]=rotr_epi32(x.v[1],n); return r; }
static inline m8 m8_srli(m8 x, int n){ m8 r; r.v[0]=_mm256_srli_epi32(x.v[0],n); r.v[1]=_mm256_srli_epi32(x.v[1],n); return r; }
static inline m8 m8_set1(uint32_t k){ m8 r; r.v[0]=_mm256_set1_epi32(k); r.v[1]=r.v[0]; return r; }
static inline m8 m8_bswap(m8 x){ m8 r; r.v[0]=bswap_epi32(x.v[0]); r.v[1]=bswap_epi32(x.v[1]); return r; }

// Load 8 lanes of word i (each message block is 64 bytes, word i at offset 4*i)
static inline m8 load_word(const uint8_t *blocks[8], int i) {
    uint32_t tmp[8];
    for (int l = 0; l < 8; l++) tmp[l] = *(const uint32_t*)(blocks[l] + 4*i);
    m8 r;
    r.v[0] = _mm256_loadu_si256((const __m256i*)tmp);
    r.v[1] = _mm256_loadu_si256((const __m256i*)(tmp+4));
    return m8_bswap(r);
}

static void sha256_8way(uint32_t state[8][8], const uint8_t *blocks[8]) {
    m8 W[64];
    for (int i = 0; i < 16; i++) W[i] = load_word(blocks, i);
    for (int i = 16; i < 64; i++) {
        m8 s0 = m8_xor(m8_xor(m8_rotr(W[i-15],7), m8_rotr(W[i-15],18)), m8_srli(W[i-15],3));
        m8 s1 = m8_xor(m8_xor(m8_rotr(W[i-2],17), m8_rotr(W[i-2],19)), m8_srli(W[i-2],10));
        W[i] = m8_add(m8_add(W[i-16], s0), m8_add(W[i-7], s1));
    }
    m8 a,b,c,d,e,f,g,h;
    // pack state: state[lane][word]
    uint32_t sa[8],sb[8],sc[8],sd[8],se[8],sf[8],sg[8],sh[8];
    for (int l=0;l<8;l++){ sa[l]=state[l][0]; sb[l]=state[l][1]; sc[l]=state[l][2]; sd[l]=state[l][3];
                           se[l]=state[l][4]; sf[l]=state[l][5]; sg[l]=state[l][6]; sh[l]=state[l][7]; }
    a.v[0]=_mm256_loadu_si256((__m256i*)sa); a.v[1]=_mm256_loadu_si256((__m256i*)(sa+4));
    b.v[0]=_mm256_loadu_si256((__m256i*)sb); b.v[1]=_mm256_loadu_si256((__m256i*)(sb+4));
    c.v[0]=_mm256_loadu_si256((__m256i*)sc); c.v[1]=_mm256_loadu_si256((__m256i*)(sc+4));
    d.v[0]=_mm256_loadu_si256((__m256i*)sd); d.v[1]=_mm256_loadu_si256((__m256i*)(sd+4));
    e.v[0]=_mm256_loadu_si256((__m256i*)se); e.v[1]=_mm256_loadu_si256((__m256i*)(se+4));
    f.v[0]=_mm256_loadu_si256((__m256i*)sf); f.v[1]=_mm256_loadu_si256((__m256i*)(sf+4));
    g.v[0]=_mm256_loadu_si256((__m256i*)sg); g.v[1]=_mm256_loadu_si256((__m256i*)(sg+4));
    h.v[0]=_mm256_loadu_si256((__m256i*)sh); h.v[1]=_mm256_loadu_si256((__m256i*)(sh+4));

    for (int i = 0; i < 64; i++) {
        m8 S1 = m8_xor(m8_xor(m8_rotr(e,6), m8_rotr(e,11)), m8_rotr(e,25));
        m8 ch = m8_xor(m8_and(e,f), m8_and(m8_not(e), g));
        m8 t1 = m8_add(m8_add(m8_add(h, S1), m8_add(ch, m8_set1(K[i]))), W[i]);
        m8 S0 = m8_xor(m8_xor(m8_rotr(a,2), m8_rotr(a,13)), m8_rotr(a,22));
        m8 maj = m8_xor(m8_xor(m8_and(a,b), m8_and(a,c)), m8_and(b,c));
        m8 t2 = m8_add(S0, maj);
        h=g; g=f; f=e; e=m8_add(d,t1); d=c; c=b; b=a; a=m8_add(t1,t2);
    }
    // store back
    uint32_t oa[8],ob[8],oc[8],od[8],oe[8],of_[8],og[8],oh[8];
    _mm256_storeu_si256((__m256i*)oa, a.v[0]); _mm256_storeu_si256((__m256i*)(oa+4), a.v[1]);
    _mm256_storeu_si256((__m256i*)ob, b.v[0]); _mm256_storeu_si256((__m256i*)(ob+4), b.v[1]);
    _mm256_storeu_si256((__m256i*)oc, c.v[0]); _mm256_storeu_si256((__m256i*)(oc+4), c.v[1]);
    _mm256_storeu_si256((__m256i*)od, d.v[0]); _mm256_storeu_si256((__m256i*)(od+4), d.v[1]);
    _mm256_storeu_si256((__m256i*)oe, e.v[0]); _mm256_storeu_si256((__m256i*)(oe+4), e.v[1]);
    _mm256_storeu_si256((__m256i*)of_, f.v[0]); _mm256_storeu_si256((__m256i*)(of_+4), f.v[1]);
    _mm256_storeu_si256((__m256i*)og, g.v[0]); _mm256_storeu_si256((__m256i*)(og+4), g.v[1]);
    _mm256_storeu_si256((__m256i*)oh, h.v[0]); _mm256_storeu_si256((__m256i*)(oh+4), h.v[1]);
    for (int l=0;l<8;l++){
        state[l][0]+=oa[l]; state[l][1]+=ob[l]; state[l][2]+=oc[l]; state[l][3]+=od[l];
        state[l][4]+=oe[l]; state[l][5]+=of_[l]; state[l][6]+=og[l]; state[l][7]+=oh[l];
    }
}

// Hash 8 independent buffers of equal length (multiple of 64) — throughput test, no padding
static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec + t.tv_nsec/1e9; }

int main(){
    size_t n = 20000ull*1024;
    // align to 64
    n = (n/64)*64;
    uint8_t *bufs[8];
    for(int i=0;i<8;i++){ bufs[i]=aligned_alloc(64, n); memset(bufs[i], 0x5a+i, n); }
    uint32_t state[8][8];
    const uint32_t IV[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};

    // warmup
    size_t blocks = n/64;
    for(int l=0;l<8;l++) memcpy(state[l], IV, 32);
    for(size_t b=0;b<blocks;b++){
        const uint8_t *bp[8];
        for(int l=0;l<8;l++) bp[l]=bufs[l]+b*64;
        sha256_8way(state, bp);
    }
    double t0=now();
    int iters=3;
    for(int it=0; it<iters; it++){
        for(int l=0;l<8;l++) memcpy(state[l], IV, 32);
        for(size_t b=0;b<blocks;b++){
            const uint8_t *bp[8];
            for(int l=0;l<8;l++) bp[l]=bufs[l]+b*64;
            sha256_8way(state, bp);
        }
    }
    double t1=now();
    double bytes = (double)n*8*iters;
    printf("8-way AVX2: %.3f s total, throughput %.1f MB/s (per-buffer equiv %.4f s for 20MB)\n",
           t1-t0, bytes/(t1-t0)/1e6, (t1-t0)/iters/8.0);
    return 0;
}
