static inline __m128i R(__m128i x, int n){ return _mm_or_si128(_mm_srli_epi32(x,n), _mm_slli_epi32(x,32-n)); }
static inline __m128i BS(__m128i x){
    const __m128i m = _mm_set_epi8(12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3);
    return _mm_shuffle_epi8(x, m);
