// 4-way SHA-256 of one block each. blocks[lane] points to 64 bytes.
static void sha256_4way(__m128i S[8], const uint8_t *b0, const uint8_t *b1, const uint8_t *b2, const uint8_t *b3) {
    __m128i W[64];
    for (int i = 0; i < 16; i++) {
        __m128i w = _mm_set_epi32(*(int*)(b3+4*i), *(int*)(b2+4*i), *(int*)(b1+4*i), *(int*)(b0+4*i));
        W[i] = BS(w);
    }
    for (int i = 16; i < 64; i++) {
        __m128i w15 = W[i-15], w2 = W[i-2];
        __m128i s0 = _mm_xor_si128(_mm_xor_si128(R(w15,7), R(w15,18)), _mm_srli_epi32(w15,3));
        __m128i s1 = _mm_xor_si128(_mm_xor_si128(R(w2,17), R(w2,19)), _mm_srli_epi32(w2,10));
        W[i] = _mm_add_epi32(_mm_add_epi32(W[i-16], s0), _mm_add_epi32(W[i-7], s1));
