#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>

// 8-way AVX2 SHA-256. Input is pre-transposed: for each block index, we have 8 lanes x 16 words
// stored as 16 x __m256i (word-major). Here we benchmark the kernel assuming data already transposed,
// AND we include a transpose cost measured separately.

static inline __m256i R(__m256i x, int n){ return _mm256_or_si256(_mm256_srli_epi32(x,n), _mm256_slli_epi32(x,32-n)); }
static inline __m256i BS(__m256i x){
    const __m256i m = _mm256_set_epi8(12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3,
                                      12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3);
    return _mm256_shuffle_epi8(x, m);
}

#define ROUND(a,b,c,d,e,f,g,h,k,w) do { \
    __m256i S1 = _mm256_xor_si256(_mm256_xor_si256(R(e,6), R(e,11)), R(e,25)); \
    __m256i ch = _mm256_xor_si256(_mm256_and_si256(e,f), _mm256_andnot_si256(e,g)); \
    __m256i t1 = _mm256_add_epi32(_mm256_add_epi32(_mm256_add_epi32(h,S1), _mm256_add_epi32(ch, _mm256_set1_epi32(k))), w); \
    __m256i S0 = _mm256_xor_si256(_mm256_xor_si256(R(a,2), R(a,13)), R(a,22)); \
    __m256i maj = _mm256_xor_si256(_mm256_xor_si256(_mm256_and_si256(a,b), _mm256_and_si256(a,c)), _mm256_and_si256(b,c)); \
