} while(0)

#define WS(i) do { \
    __m256i w15=W[(i-15)&15], w2=W[(i-2)&15]; \
    __m256i s0=_mm256_xor_si256(_mm256_xor_si256(R(w15,7),R(w15,18)),_mm256_srli_epi32(w15,3)); \
    __m256i s1=_mm256_xor_si256(_mm256_xor_si256(R(w2,17),R(w2,19)),_mm256_srli_epi32(w2,10)); \
    W[i&15]=_mm256_add_epi32(_mm256_add_epi32(W[i&15],s0),_mm256_add_epi32(W[(i-7)&15],s1)); \
} while(0)

static const uint32_t KK[64]={
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};

// W_in[16] are the 16 message words, each holding 8 lanes, already byte-swapped.
static void sha256_8way(__m256i S[8], const __m256i *Win) {
    __m256i W[16];
    for(int i=0;i<16;i++) W[i]=Win[i];
    __m256i a=S[0],b=S[1],c=S[2],d=S[3],e=S[4],f=S[5],g=S[6],h=S[7];
    #define STEP(i) do { if(i>=16) WS(i); ROUND(a,b,c,d,e,f,g,h, KK[i], W[i&15]); } while(0)
    STEP(0);STEP(1);STEP(2);STEP(3);STEP(4);STEP(5);STEP(6);STEP(7);
    STEP(8);STEP(9);STEP(10);STEP(11);STEP(12);STEP(13);STEP(14);STEP(15);
    STEP(16);STEP(17);STEP(18);STEP(19);STEP(20);STEP(21);STEP(22);STEP(23);
    STEP(24);STEP(25);STEP(26);STEP(27);STEP(28);STEP(29);STEP(30);STEP(31);
    STEP(32);STEP(33);STEP(34);STEP(35);STEP(36);STEP(37);STEP(38);STEP(39);
    STEP(40);STEP(41);STEP(42);STEP(43);STEP(44);STEP(45);STEP(46);STEP(47);
    STEP(48);STEP(49);STEP(50);STEP(51);STEP(52);STEP(53);STEP(54);STEP(55);
    STEP(56);STEP(57);STEP(58);STEP(59);STEP(60);STEP(61);STEP(62);STEP(63);
    S[0]=_mm256_add_epi32(S[0],a); S[1]=_mm256_add_epi32(S[1],b);
    S[2]=_mm256_add_epi32(S[2],c); S[3]=_mm256_add_epi32(S[3],d);
    S[4]=_mm256_add_epi32(S[4],e); S[5]=_mm256_add_epi32(S[5],f);
    S[6]=_mm256_add_epi32(S[6],g); S[7]=_mm256_add_epi32(S[7],h);
}

// Transpose 8 contiguous 64-byte blocks (lanes) into 16 __m256i words, byte-swapped.
// Layout in: lane l block starts at base+l*64.
static void transpose8(const uint8_t *base, __m256i out[16]) {
    // Load 8 x 64 bytes = 8 x 4 ymm? Each lane is 64 bytes = 2 ymm. We want word-major of 8 lanes.
    // Simpler scalar gather into array then vector load+bswap — measure it.
    uint32_t tmp[8];
    for (int w = 0; w < 16; w++) {
        for (int l = 0; l < 8; l++) tmp[l] = *(const uint32_t*)(base + l*64 + 4*w);
        out[w] = BS(_mm256_loadu_si256((const __m256i*)tmp));
    }
}

static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9; }

int main(){
    size_t n=(20000ull*1024/512)*512; // multiple of 8*64
    int LANES=8;
    uint8_t *buf = aligned_alloc(64, n);
    memset(buf, 0x5a, n);
    size_t groups = n / (64*LANES);
    __m256i *pre = aligned_alloc(32, groups*16*sizeof(__m256i));
    double t0=now();
    for(size_t g=0; g<groups; g++) transpose8(buf + g*64*LANES, pre + g*16);
    double t1=now();
    printf("transpose only: %.4f s for %.1f MB -> %.1f MB/s\n", t1-t0, n/1e6, (n/1e6)/(t1-t0));

    uint32_t IV[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    __m256i S[8];
    int iters=3;
    // kernel only
    for(int i=0;i<8;i++) S[i]=_mm256_set1_epi32(IV[i]);
    for(size_t g=0; g<groups; g++) sha256_8way(S, pre+g*16);
    t0=now();
    for(int it=0; it<iters; it++){
        for(int i=0;i<8;i++) S[i]=_mm256_set1_epi32(IV[i]);
        for(size_t g=0; g<groups; g++) sha256_8way(S, pre+g*16);
    }
    t1=now();
    printf("8-way kernel only: %.3f s, %.1f MB/s, per-buf-equiv %.4f s\n", t1-t0, (double)n*iters/(t1-t0)/1e6, (t1-t0)/iters);
    // combined
    t0=now();
    for(int it=0; it<iters; it++){
        for(int i=0;i<8;i++) S[i]=_mm256_set1_epi32(IV[i]);
        for(size_t g=0; g<groups; g++){
            __m256i W[16];
            transpose8(buf+g*64*LANES, W);
            sha256_8way(S, W);
        }
    }
    t1=now();
    printf("8-way combined: %.3f s, %.1f MB/s, equiv %.4f s\n", t1-t0, (double)n*iters/(t1-t0)/1e6, (t1-t0)/iters);
    return 0;
}
